SELECT b.CSNAME AS `股票名称`, a.COMB_SYMBOL AS `股票代码`, c.F013N AS `市值（百万元）`, ROUND(c.F013N / 100, 1) AS `市值（亿，保留1位小数）`, c.F014D AS `市值更新时间` FROM AMERICAN_STOCK_MAIN a INNER JOIN COM3101 c ON a.FIU_ID = c.FIU_ID INNER JOIN AMERICAN_STOCK_MAIN b ON c.FIU_ID = b.FIU_ID WHERE (a.COMB_SYMBOL IN ('AAPL.US', 'MSFT.US', 'NVDA.US') OR b.CSNAME LIKE '%苹果%' OR b.CSNAME LIKE '%微软%' OR b.CSNAME LIKE '%英伟达%' OR b.CSNAME LIKE '%Apple%' OR b.CSNAME LIKE '%Microsoft%' OR b.CSNAME LIKE '%NVIDIA%') AND c.F013N IS NOT NULL ORDER BY c.F013N DESC LIMIT 1;
